"""HTML developer dashboard for eDocAPI applications."""

from __future__ import annotations

import html
import json


def render_dashboard(routes: list[dict], formats: list[str], max_file_size: int) -> str:
    route_rows = "".join(
        f'<tr><td><span class="method">{html.escape(", ".join(r["methods"]))}</span></td>'
        f'<td><code>{html.escape(r["path"])}</code></td><td>{html.escape(r["name"])}</td></tr>'
        for r in routes
    ) or '<tr><td colspan="3" class="empty">No custom routes yet. Add a route decorator to your app.</td></tr>'
    format_cards = "".join(f'<span class="format">{html.escape(x.upper())}</span>' for x in formats)
    size = f"{max_file_size / 1024 / 1024:g} MB"
    route_data = html.escape(json.dumps(routes))
    return f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="theme-color" content="#101411"><title>eDocAPI · Developer Console</title>
<style>
:root{{--bg:#101411;--panel:#171d19;--line:#29332d;--muted:#94a399;--text:#edf5ef;--green:#a8f078;--mint:#6ee7b7;--orange:#ffc078}}
*{{box-sizing:border-box}}body{{margin:0;background:radial-gradient(ellipse at 82% 0%,#24392c 0,transparent 36%),var(--bg);color:var(--text);font:15px/1.5 Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif}}a{{color:var(--green);text-decoration:none}}a:hover{{text-decoration:underline}}.shell{{max-width:1180px;margin:auto;padding:28px 24px 60px}}header{{display:flex;align-items:center;justify-content:space-between;margin-bottom:58px}}.brand{{display:flex;gap:12px;align-items:center;font-weight:750;letter-spacing:-.03em;font-size:19px}}.mark{{width:38px;height:38px;border-radius:12px;background:linear-gradient(135deg,var(--green),var(--mint));color:#102016;display:grid;place-items:center;font-weight:900;font-size:19px;box-shadow:0 8px 32px #83ef8130}}.badge{{border:1px solid var(--line);border-radius:99px;padding:6px 12px;color:var(--muted);font-size:12px}}.hero{{max-width:760px;margin-bottom:34px}}.eyebrow{{color:var(--green);font-size:12px;text-transform:uppercase;font-weight:800;letter-spacing:.15em}}h1{{font-size:clamp(38px,6vw,66px);line-height:1.02;letter-spacing:-.065em;margin:13px 0 17px}}h1 span{{color:var(--green)}}.lead{{color:#aab8ae;font-size:17px;max-width:630px}}.actions{{display:flex;gap:10px;margin-top:24px;flex-wrap:wrap}}.button{{border:1px solid var(--line);border-radius:10px;padding:10px 15px;background:#1d2720;color:var(--text);font-weight:650}}.button.primary{{background:var(--green);border-color:var(--green);color:#122014}}.stats{{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin:32px 0}}.stat,.panel{{background:linear-gradient(145deg,#1a211c,#151a17);border:1px solid var(--line);border-radius:15px}}.stat{{padding:18px 20px}}.stat small,.muted{{color:var(--muted)}}.stat strong{{display:block;font-size:27px;letter-spacing:-.04em;margin-top:4px}}.grid{{display:grid;grid-template-columns:1.15fr .85fr;gap:16px}}.panel{{padding:22px}}.panel h2{{font-size:16px;margin:0 0 16px;letter-spacing:-.02em}}table{{width:100%;border-collapse:collapse;text-align:left}}th{{color:var(--muted);font-size:11px;text-transform:uppercase;letter-spacing:.1em;font-weight:650}}td,th{{padding:12px 8px;border-bottom:1px solid #29332d}}td{{font-size:13px}}td code,.code{{font-family:ui-monospace,SFMono-Regular,Consolas,monospace;color:#c8f4a5}}.method{{font-size:10px;font-weight:800;color:var(--mint);background:#16352c;padding:4px 7px;border-radius:5px}}.empty{{color:var(--muted);padding:20px 8px}}.formats{{display:flex;gap:7px;flex-wrap:wrap}}.format{{border:1px solid #35433a;background:#202a23;color:#c4d7c8;padding:5px 9px;border-radius:7px;font-size:11px;font-weight:750;letter-spacing:.05em}}.codebox{{background:#0e120f;border:1px solid var(--line);border-radius:10px;padding:14px;margin-top:13px;overflow:auto;color:#c5d3c8;font:12px/1.8 ui-monospace,SFMono-Regular,Consolas,monospace}}.accent{{color:var(--orange)}}.span2{{grid-column:1/-1}}.footer{{color:#718078;font-size:12px;margin-top:26px;display:flex;justify-content:space-between;gap:12px}}@media(max-width:760px){{header{{margin-bottom:38px}}.grid{{grid-template-columns:1fr}}.span2{{grid-column:auto}}.stats{{gap:8px}}.stat{{padding:14px}}.stat strong{{font-size:22px}}.shell{{padding:20px 16px 40px}}}}
</style></head><body><main class="shell">
<header><div class="brand"><div class="mark">e</div><span>eDocAPI <span class="muted">/ console</span></span></div><div class="badge">DOCUMENT API FRAMEWORK · v0.0.2</div></header>
<section class="hero"><div class="eyebrow">Your document workflow, at a glance</div><h1>Build APIs.<br><span>Move documents.</span></h1><p class="lead">A developer console for your eDocAPI application. Explore your routes, supported formats, and the document operations ready to power your API.</p><div class="actions"><a class="button primary" href="#routes">Explore routes ↓</a><a class="button" href="https://github.com/emmanuelemmanueletim/edocApi">Framework docs ↗</a></div></section>
<section class="stats"><div class="stat"><small>Registered routes</small><strong>{len(routes):02d}</strong></div><div class="stat"><small>Supported formats</small><strong>{len(formats):02d}</strong></div><div class="stat"><small>Upload limit</small><strong>{html.escape(size)}</strong></div></section>
<section class="grid"><div class="panel" id="routes"><h2>⌘ &nbsp;Your API routes</h2><table><thead><tr><th>Method</th><th>Path</th><th>Handler</th></tr></thead><tbody>{route_rows}</tbody></table></div>
<div class="panel"><h2>▧ &nbsp;Format support</h2><p class="muted" style="font-size:13px;margin-top:-5px">Recognized input types from your installed processors.</p><div class="formats">{format_cards}</div><h2 style="margin-top:24px">✳ &nbsp;Document toolkit</h2><p class="muted" style="font-size:13px;margin-top:-5px">Methods available on <span class="code">Document</span></p><div class="codebox">to_pdf() &nbsp;·&nbsp; to_text() &nbsp;·&nbsp; to_html()<br>to_images() &nbsp;·&nbsp; extract_text() &nbsp;·&nbsp; info()<br><span class="accent">PDF:</span> compress() &nbsp;·&nbsp; split() &nbsp;·&nbsp; extract_pages()<br>rotate() &nbsp;·&nbsp; Document.merge(files)</div></div>
<div class="panel span2"><h2>⚡ &nbsp;Start building</h2><p class="muted" style="font-size:13px;margin-top:-5px">Create a route in <span class="code">main.py</span>, then start the development server with auto-reload.</p><div class="codebox">from edocapi import App, Document<br><br>app = App()<br><br>@app.post("/convert")<br>def convert(file):<br>&nbsp;&nbsp;&nbsp;&nbsp;return Document(file).to_pdf()<br><br># Terminal: edocapi run --reload</div></div></section>
<footer class="footer"><span>eDocAPI · Simple API for the developer. Powerful document processing underneath.</span><span>Auto-generated from your app configuration</span></footer></main>
<script type="application/json" id="edocapi-routes">{route_data}</script></body></html>'''
